const visual = {
  prepare: function (input) {
    var reqs = [];
    for (var v = -5; v <= 5; v++) {
      reqs.push({ kind: 'text', payload: String(v) });
    }
    return reqs;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var m = Math.max(44, Math.round(W * 0.08));
    var x0 = m;
    var x1 = W - m;
    var y = Math.round(H * 0.58);

    var axisCmds = visualSdk.axis({ x0: x0, y0: y, x1: x1, y1: y, ticks: 11, tickLength: 8 });

    var labels = [];
    var count = 11;
    for (var i = 0; i < count; i++) {
      var t = i / (count - 1);
      var tx = x0 + (x1 - x0) * t;
      var text = String(-5 + i);
      var mm = (metrics && metrics[i]) ? metrics[i] : null;
      var tw = (mm && typeof mm.width === 'number') ? mm.width : text.length * 8;
      var th = (mm && typeof mm.height === 'number') ? mm.height : 12;
      labels.push({
        type: 'label',
        text: text,
        x: tx,
        y: y + 14 + th * 0.85,
        textAnchor: 'middle',
        fontSize: 13,
        fill: '#26354a',
        meta: { tickIndex: i, tickX: tx, value: -5 + i, measuredWidth: tw }
      });
    }

    var children = [{ type: 'path', pathId: 'axis', stroke: '#26354a', strokeWidth: 1.5 }];
    for (var k = 0; k < labels.length; k++) children.push(labels[k]);

    return {
      schemaVersion: 1,
      sceneId: 'axis-minus5-to-5-11ticks',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'axis', commands: axisCmds }],
      root: { type: 'group', children: children }
    };
  }
};
